"""Bounded, archived cleanup of regenerated bytecode in one isolated CGX review worktree.

No canonical source, carrier, runtime, database, parent checkout, symlink/junction,
research sentinel, node_modules or dist path can be removed by this tool.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import stat
import subprocess
import zipfile
from datetime import datetime, timezone
from pathlib import Path

EXPECTED_BRANCH = "review/cgx-living-consolidation-20261118"
EXPECTED_WORKTREE_NAME = "CGX_Mobile_Review"
CONFIRM = "PURGE_REGENERABLE_REVIEW_BYTECODE_ONLY"
ALLOW = (
    "tests/__pycache__",
    "tools/__pycache__",
    "desktop/LightSpeed_Runtime/tests/__pycache__",
    "desktop/LightSpeed_Runtime/lightspeed_runtime/__pycache__",
)
EXTENSIONS = {".pyc", ".pyo"}
MAX_FILE_BYTES = 16 * 1024 * 1024
MAX_TOTAL_BYTES = 64 * 1024 * 1024
MAX_FILES = 2000
SCHEMA = "CGX-BOUNDED-LOCAL-CACHE-CLEANUP/0.1"


class CleanupHold(ValueError):
    pass


def _not_link(path: Path) -> bool:
    try:
        info = path.lstat()
    except OSError as exc:
        raise CleanupHold("path inaccessible during cleanup review") from exc
    return not (path.is_symlink() or
                bool(getattr(info, "st_file_attributes", 0) &
                     getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)))


def _git(repo: Path, *params: str) -> str:
    try:
        p = subprocess.run(["git", "-C", str(repo), *params],
                           capture_output=True, check=False, timeout=18)
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise CleanupHold("Git worktree verification unavailable") from exc
    if p.returncode:
        raise CleanupHold("Git worktree cannot be verified")
    return p.stdout.decode("utf-8", errors="strict").strip()


def _sha(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def scan(repo: Path) -> dict:
    repo = Path(repo).resolve(strict=True)
    if repo.name != EXPECTED_WORKTREE_NAME or not repo.is_dir():
        raise CleanupHold("target is not the isolated review worktree")
    branch = _git(repo, "branch", "--show-current")
    if branch != EXPECTED_BRANCH:
        raise CleanupHold("review branch identity changed")
    if _git(repo, "status", "--porcelain"):
        raise CleanupHold("unclean worktree: no deletion while edits are present")
    head = _git(repo, "rev-parse", "HEAD")
    tracked = set(_git(repo, "ls-files", "-z").split("\x00"))
    candidates: list[dict] = []
    for relative in ALLOW:
        folder = repo / relative
        if not folder.exists():
            continue
        if not folder.is_dir() or not _not_link(folder) or not folder.resolve().is_relative_to(repo):
            raise CleanupHold("untrusted or linked cache directory")
        descendants = sorted(folder.rglob("*"), key=lambda p: str(p).casefold())
        for path in descendants:
            if not _not_link(path):
                raise CleanupHold("linked/reparse child inside cache")
            if not path.resolve().is_relative_to(repo):
                raise CleanupHold("cache traversal outside review worktree")
            if path.is_dir():
                continue
            rel = path.relative_to(repo).as_posix()
            if (not path.is_file() or path.suffix.lower() not in EXTENSIONS
                    or rel in tracked or len(candidates) >= MAX_FILES):
                raise CleanupHold("non-bytecode, tracked, or unbounded cache candidate")
            info = path.stat()
            if info.st_size > MAX_FILE_BYTES or info.st_size < 0 or info.st_nlink != 1:
                raise CleanupHold("unsafe cache file size or hardlink")
            raw = path.read_bytes()
            if len(raw) != info.st_size:
                raise CleanupHold("cache changed while scanning")
            candidates.append({"path": rel, "sha256": _sha(raw),
                               "size_bytes": len(raw), "mtime_ns": info.st_mtime_ns})
    if sum(x["size_bytes"] for x in candidates) > MAX_TOTAL_BYTES:
        raise CleanupHold("cleanup exceeds byte budget")
    candidates.sort(key=lambda x: x["path"])
    proof = {
        "schema": SCHEMA,
        "worktree": str(repo),
        "branch": branch,
        "head": head,
        "candidates": candidates,
        "candidate_count": len(candidates),
        "candidate_bytes": sum(x["size_bytes"] for x in candidates),
        "exclusions": [
            "tracked source", "T174 and research scaffolds", "canonical carriers",
            "live database", "node_modules junction and caches", "built dist",
            "other Git worktrees", "native runtime", "authority or DBR receipts"
        ],
        "canonical_runtime_changed": False,
        "mint_authorized": False,
        "source_or_carrier_deletion_authorized": False,
    }
    proof["scan_sha256"] = _sha(json.dumps(proof, sort_keys=True,
                                          separators=(",", ":"), ensure_ascii=True).encode("ascii"))
    return proof


def _same(repo: Path, item: dict) -> bool:
    path = repo / item["path"]
    if not path.is_file() or not _not_link(path) or not path.resolve().is_relative_to(repo):
        return False
    info = path.stat()
    if info.st_size != item["size_bytes"] or info.st_mtime_ns != item["mtime_ns"]:
        return False
    return _sha(path.read_bytes()) == item["sha256"]


def execute(repo: Path, archive_dir: Path, *, confirm: str) -> dict:
    if confirm != CONFIRM:
        raise CleanupHold("explicit narrow deletion confirmation missing")
    repo = Path(repo).resolve(strict=True)
    proof = scan(repo)
    if not proof["candidates"]:
        return {**proof, "state": "NO_CACHE_CANDIDATES", "deleted_files": 0}
    archive_dir = Path(archive_dir).absolute()
    if archive_dir.exists() and (
        not archive_dir.is_dir() or not _not_link(archive_dir)
        or archive_dir.resolve().is_relative_to(repo)
    ):
        raise CleanupHold("archive location must be an independent ordinary directory")
    # Avoid storing archives inside live root, a mounted CGX carrier, or Git workspace.
    canonical_archive = archive_dir.resolve()
    if any(str(canonical_archive).casefold().startswith(str(p).casefold())
           for p in (repo, repo.parent / "LightSpeed_Canonical")):
        raise CleanupHold("archive location overlaps a source worktree")
    # Establish a single verified snapshot; any race invalidates the operation.
    for item in proof["candidates"]:
        if not _same(repo, item):
            raise CleanupHold("cache changed before archive; scan again")
    archive_dir.mkdir(parents=True, exist_ok=True)
    archive = archive_dir / ("cgx-review-bytecode-" + proof["scan_sha256"][:16] + ".zip")
    receipt = archive.with_suffix(".receipt.json")
    if archive.exists() or receipt.exists():
        raise CleanupHold("immutable archive/receipt already exists")
    temp = archive.with_suffix(".partial")
    payload = json.dumps(proof, sort_keys=True, ensure_ascii=True, indent=2).encode("ascii")
    try:
        with zipfile.ZipFile(temp, "w", compression=zipfile.ZIP_STORED) as target:
            target.writestr("MANIFEST.json", payload)
            for item in proof["candidates"]:
                if not _same(repo, item):
                    raise CleanupHold("cache changed while archiving")
                target.write(repo / item["path"], "cache/" + item["path"])
        with zipfile.ZipFile(temp, "r") as witness:
            if witness.read("MANIFEST.json") != payload:
                raise CleanupHold("archived manifest readback mismatch")
            if len(witness.namelist()) != len(proof["candidates"]) + 1:
                raise CleanupHold("archive count mismatch")
            for item in proof["candidates"]:
                if _sha(witness.read("cache/" + item["path"])) != item["sha256"]:
                    raise CleanupHold("byte-exact archive verification failed")
        os.replace(temp, archive)
    finally:
        if temp.exists():
            temp.unlink()
    deleted = []
    held = []
    for item in proof["candidates"]:
        if not _same(repo, item):
            held.append(item["path"])
            continue
        path = repo / item["path"]
        try:
            path.unlink()
            deleted.append(item["path"])
        except OSError:
            held.append(item["path"])
    for relative in ALLOW:
        folder = repo / relative
        if folder.is_dir() and _not_link(folder):
            for directory in sorted((p for p in folder.rglob("*") if p.is_dir()),
                                    key=lambda p: len(p.parts), reverse=True):
                try:
                    directory.rmdir()
                except OSError:
                    pass
            try:
                folder.rmdir()
            except OSError:
                pass
    result = {
        "schema": SCHEMA,
        "state": "VERIFIED_BYTECODE_PURGED" if not held else "PARTIAL_HOLD",
        "scan_sha256": proof["scan_sha256"],
        "commit": proof["head"],
        "archive": str(archive),
        "archive_sha256": _sha(archive.read_bytes()),
        "deleted_files": len(deleted),
        "deleted_bytes": sum(x["size_bytes"] for x in proof["candidates"]
                             if x["path"] in set(deleted)),
        "held_files": held,
        "source_git_clean_after": _git(repo, "status", "--porcelain") == "",
        "rollback_instruction": "Restore only cache/ members from ZIP into this isolated worktree",
        "canonical_runtime_changed": False,
        "carrier_or_source_deleted": False,
        "native_mint_or_network_activated": False,
        "completed_utc": datetime.now(timezone.utc).isoformat(),
    }
    if not result["source_git_clean_after"]:
        result["state"] = "HOLD_WORKTREE_CHANGED"
    receipt.write_text(json.dumps(result, sort_keys=True, indent=2), encoding="utf-8")
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--archive-dir", type=Path,
                        default=Path(r"D:\LightSpeed\State\Review\CGX_CacheCleanup_20261118"))
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--confirm", default="")
    args = parser.parse_args()
    try:
        report = (execute(args.repo, args.archive_dir, confirm=args.confirm)
                  if args.execute else scan(args.repo))
    except (CleanupHold, OSError, ValueError) as exc:
        print(json.dumps({"schema": SCHEMA, "state": "HOLD", "reason": str(exc),
                          "deleted_files": 0}, sort_keys=True))
        return 2
    print(json.dumps(report, sort_keys=True, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
